 public async Task Ask(DiscoveryCommand i)
 {
  Signed();Validate(i);Need(i.SubmissionId!=Guid.Empty&&!string.IsNullOrWhiteSpace(i.Body),"Nhập câu hỏi của bạn.");Need(i.Body.Length<=1000,"Câu hỏi tối đa 1000 ký tự.");await travel.Execute(async()=>{if(await db.Set<DiscoveryQuestion>().AnyAsync(x=>x.OwnerId==Me&&x.SubmissionId==i.SubmissionId))return;await PublicEntry(i.EntryId);Need(await db.Set<DiscoveryQuestion>().CountAsync(x=>x.OwnerId==Me&&x.CreatedAt>clock.BayGioUtc.AddMinutes(-10))<5,"Bạn vừa gửi nhiều câu hỏi. Hãy chờ ít phút rồi thử lại.",429);db.Add(new DiscoveryQuestion{EntryId=i.EntryId,OwnerId=Me,Question=i.Body.Trim(),SubmissionId=i.SubmissionId,Status="Pending",CreatedAt=clock.BayGioUtc,UpdatedAt=clock.BayGioUtc});audit.Ghi("HoiThongTin","DiscoveryEntry",i.EntryId,null,"Pending");});
 }
 public async Task Answer(DiscoveryCommand i)
 {
  travel.RoleRequired(TravelService.AdminRole,TravelService.ProviderRole);Validate(i);Need(new[]{"Answer","Hide"}.Contains(i.Decision),"Thao tác hỏi đáp không hợp lệ.");Need(DiscoveryText.HttpUrl(i.Source),"Nguồn trả lời cần là HTTPS hợp lệ.");await travel.Execute(async()=>{var q=await db.Set<DiscoveryQuestion>().SingleOrDefaultAsync(x=>x.Id==i.Id)??throw new BusinessException("Không tìm thấy câu hỏi.",404);await Editable(q.EntryId);Version(q,i.Version);if(!Admin)Need(q.Status=="Pending"&&i.Decision=="Answer","Chỉ trả lời câu hỏi đang chờ; quản trị viên kiểm tra trước khi công bố.",403);if(i.Decision=="Hide"){Need(!string.IsNullOrWhiteSpace(i.Reason),"Ghi lý do ẩn câu hỏi.");q.Status="Hidden";}else{Need(!string.IsNullOrWhiteSpace(i.Text)&&i.Text.Length<=4000,"Nhập câu trả lời tối đa 4000 ký tự.");q.Answer=i.Text.Trim();q.AnswerSource=Clean(i.Source);q.AnsweredBy=Me;q.AnsweredAt=clock.BayGioUtc;q.Status=Admin?"Answered":"Pending";}q.UpdatedAt=clock.BayGioUtc;audit.Ghi("XuLyHoiDap","DiscoveryQuestion",q.Id,null,q.Status,i.Reason);if(Admin)notices.Tao(q.OwnerId,"TraLoiThongTin",q.Status=="Answered"?"Câu hỏi của bạn đã được trả lời và kiểm tra.":"Câu hỏi của bạn đã được xem xét: "+i.Reason,DiscoveryText.Link(q.EntryId)+"#questions");});
 }
 public async Task Experience(DiscoveryCommand i)
 {
  travel.RoleRequired(TravelService.Traveler);Validate(i);Need(i.SubmissionId!=Guid.Empty&&!string.IsNullOrWhiteSpace(i.Name)&&!string.IsNullOrWhiteSpace(i.Body),"Nhập tiêu đề và nội dung kinh nghiệm.");Need(i.VisitedOn!=null&&i.VisitedOn<=clock.HomNay&&i.VisitedOn>=new DateOnly(2000,1,1),"Chọn ngày trải nghiệm đã diễn ra.");var topics=i.Topics.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).Distinct().ToList();Need(topics.Count>0&&topics.All(DiscoveryText.Topics.ContainsKey),"Chọn ít nhất một chủ đề kinh nghiệm hợp lệ.");await travel.Execute(async()=>{if(await db.Set<DiscoveryExperience>().AnyAsync(x=>x.OwnerId==Me&&x.SubmissionId==i.SubmissionId))return;var e=await PublicEntry(i.EntryId);Need(e.ServiceId==null,"Đánh giá dịch vụ cần thực hiện từ yêu cầu đặt đã sử dụng.");Need(!await db.Set<DiscoveryExperience>().AnyAsync(x=>x.OwnerId==Me&&x.EntryId==e.Id&&x.VisitedOn==i.VisitedOn&&x.Status!="Hidden"),"Bạn đã gửi kinh nghiệm cho địa điểm này vào ngày đã chọn.",409);db.Add(new DiscoveryExperience{EntryId=e.Id,OwnerId=Me,Title=i.Name.Trim(),Body=i.Body.Trim(),Topics=string.Join(',',topics),VisitedOn=i.VisitedOn!.Value,Rating=i.Rating,Status="Pending",SubmissionId=i.SubmissionId,CreatedAt=clock.BayGioUtc,UpdatedAt=clock.BayGioUtc});});
 }
 public async Task ModerateExperience(DiscoveryCommand i)
 {
  travel.RoleRequired(TravelService.AdminRole);Need(new[]{"Published","Hidden"}.Contains(i.Decision)&&!string.IsNullOrWhiteSpace(i.Reason),"Chọn kết quả và ghi lý do kiểm duyệt.");await travel.Execute(async()=>{var x=await db.Set<DiscoveryExperience>().SingleOrDefaultAsync(x=>x.Id==i.Id)??throw new BusinessException("Không tìm thấy kinh nghiệm.",404);Version(x,i.Version);x.Status=i.Decision;x.ModeratedBy=Me;x.ModerationNote=i.Reason;x.UpdatedAt=clock.BayGioUtc;audit.Ghi("KiemDuyetKinhNghiem","DiscoveryExperience",x.Id,null,x.Status,i.Reason);notices.Tao(x.OwnerId,"KiemDuyetKinhNghiem","Kinh nghiệm của bạn đã được xem xét: "+DiscoveryText.State(x.Status),DiscoveryText.Link(x.EntryId)+"#experiences");});
 }
 public async Task Report(DiscoveryCommand i)
 {
  Signed();Validate(i);Need(i.SubmissionId!=Guid.Empty&&!string.IsNullOrWhiteSpace(i.Body),"Mô tả thông tin cần kiểm tra.");Need(new[]{"Price","Hours","Address","Accessibility","Closed","Content","Other"}.Contains(i.Decision),"Loại phản ánh không hợp lệ.");Need(DiscoveryText.HttpUrl(i.Source),"Đường dẫn bằng chứng cần là HTTPS hợp lệ.");await travel.Execute(async()=>{if(await db.Set<DiscoveryReport>().AnyAsync(x=>x.OwnerId==Me&&x.SubmissionId==i.SubmissionId))return;await PublicEntry(i.EntryId);Need(await db.Set<DiscoveryReport>().CountAsync(x=>x.OwnerId==Me&&x.CreatedAt>clock.BayGioUtc.AddMinutes(-10))<5,"Bạn vừa gửi nhiều phản ánh. Hãy chờ ít phút rồi thử lại.",429);db.Add(new DiscoveryReport{EntryId=i.EntryId,OwnerId=Me,Category=i.Decision,Body=i.Body.Trim(),EvidenceUrl=Clean(i.Source),Status="Pending",SubmissionId=i.SubmissionId,CreatedAt=clock.BayGioUtc,UpdatedAt=clock.BayGioUtc});});
 }
 public async Task HandleReport(DiscoveryCommand i)
 {
  travel.RoleRequired(TravelService.AdminRole);Need(new[]{"Checking","Resolved","Rejected"}.Contains(i.Decision)&&!string.IsNullOrWhiteSpace(i.Text),"Chọn trạng thái và ghi phản hồi cụ thể.");Need(i.Text.Length<=1000,"Phản hồi tối đa 1000 ký tự.");await travel.Execute(async()=>{var x=await db.Set<DiscoveryReport>().SingleOrDefaultAsync(x=>x.Id==i.Id)??throw new BusinessException("Không tìm thấy phản ánh.",404);Version(x,i.Version);Need(x.Status=="Pending"&&i.Decision=="Checking"||x.Status=="Checking"&&new[]{"Resolved","Rejected"}.Contains(i.Decision),"Phản ánh cần được tiếp nhận trước khi ghi kết quả.",409);x.Status=i.Decision;x.HandledBy=Me;x.Response=i.Text.Trim();x.UpdatedAt=clock.BayGioUtc;audit.Ghi("XuLyPhanAnhTraCuu","DiscoveryReport",x.Id,null,x.Status,x.Response);notices.Tao(x.OwnerId,"PhanAnhThongTin","Phản ánh của bạn: "+DiscoveryText.State(x.Status),"/Discovery/Library#reports");});
 }
 public async Task Follow(DiscoveryCommand i)
 {
  Signed();Need(new[]{"Follow","Unfollow"}.Contains(i.Decision),"Thao tác theo dõi không hợp lệ.");await travel.Execute(async()=>{if(i.Decision=="Follow")await PublicEntry(i.EntryId);var row=await db.Set<DiscoveryFollow>().SingleOrDefaultAsync(x=>x.EntryId==i.EntryId&&x.OwnerId==Me);if(row==null){Need(i.Decision=="Follow","Không tìm thấy mục theo dõi.",404);row=new(){EntryId=i.EntryId,OwnerId=Me};db.Add(row);}row.Active=i.Decision=="Follow";row.UpdatedAt=clock.BayGioUtc;});
 }
 public async Task<DiscoveryLibraryPage> Library(DiscoveryCommand? input=null)
 {
  Signed();var collections=await db.Set<DiscoveryCollection>().AsNoTracking().Where(x=>x.OwnerId==Me&&!x.Archived).OrderByDescending(x=>x.UpdatedAt).Take(30).ToListAsync();var ids=collections.Select(x=>x.Id).ToList();var items=await db.Set<DiscoveryCollectionItem>().AsNoTracking().Where(x=>ids.Contains(x.CollectionId)&&!x.Removed).ToListAsync();var follows=db.Set<DiscoveryFollow>().Where(x=>x.OwnerId==Me&&x.Active);var followedIds=await follows.Select(x=>x.EntryId).ToListAsync();var entryIds=items.Select(x=>x.EntryId).ToList();var entries=await Public().AsNoTracking().Where(x=>entryIds.Contains(x.Id)||follows.Any(f=>f.EntryId==x.Id)).ToListAsync();await Hydrate(entries);
  return new(collections,items,entries.ToDictionary(x=>x.Id),await db.Set<DiscoveryRoute>().AsNoTracking().Where(x=>x.OwnerId==Me&&!x.Archived).OrderByDescending(x=>x.UpdatedAt).Take(30).ToListAsync(),entries.Where(x=>followedIds.Contains(x.Id)).ToList(),await db.Set<DiscoveryQuestion>().AsNoTracking().Where(x=>x.OwnerId==Me).OrderByDescending(x=>x.Id).Take(50).ToListAsync(),await db.Set<DiscoveryReport>().AsNoTracking().Where(x=>x.OwnerId==Me).OrderByDescending(x=>x.Id).Take(50).ToListAsync(),input??new(),followedIds.Except(entries.Select(x=>x.Id)).ToList());
 }
 public async Task Collection(DiscoveryCommand i)
 {
  Signed();Validate(i);Need(new[]{"Create","Rename","Archive","Add","Remove","Import","Note"}.Contains(i.Decision),"Thao tác danh sách không hợp lệ.");Need(i.EntryIds.Count<=100,"Chỉ đồng bộ tối đa 100 lựa chọn mỗi lần.");await travel.Execute(async()=>{
   DiscoveryCollection c;if(i.Decision=="Create"||i.Decision=="Import"&&i.CollectionId==0){Need(!string.IsNullOrWhiteSpace(i.Name)&&i.Name.Length<=100,"Tên danh sách tối đa 100 ký tự.");c=await db.Set<DiscoveryCollection>().FirstOrDefaultAsync(x=>x.OwnerId==Me&&!x.Archived&&x.Name==i.Name.Trim())??new(){OwnerId=Me,Name=i.Name.Trim(),UpdatedAt=clock.BayGioUtc};if(c.Id==0){Need(await db.Set<DiscoveryCollection>().CountAsync(x=>x.OwnerId==Me&&!x.Archived)<30,"Bạn đã có 30 danh sách. Hãy lưu vào danh sách hiện có.");db.Add(c);await db.SaveChangesAsync();}if(i.Decision=="Create")return;}
   else c=await db.Set<DiscoveryCollection>().SingleOrDefaultAsync(x=>x.Id==i.CollectionId&&x.OwnerId==Me&&!x.Archived)??throw new BusinessException("Không tìm thấy danh sách của bạn.",404);
   if(i.Decision is "Rename" or "Archive"){Version(c,i.Version);if(i.Decision=="Archive")c.Archived=true;else{Need(!string.IsNullOrWhiteSpace(i.Name)&&i.Name.Length<=100,"Tên danh sách tối đa 100 ký tự.");c.Name=i.Name.Trim();c.Note=Clean(i.Body);}c.UpdatedAt=clock.BayGioUtc;return;}
   if(i.Decision=="Note"){Need(i.Body.Length<=500,"Ghi chú tối đa 500 ký tự.");var row=await db.Set<DiscoveryCollectionItem>().SingleOrDefaultAsync(x=>x.CollectionId==c.Id&&x.EntryId==i.EntryId&&!x.Removed)??throw new BusinessException("Không tìm thấy lựa chọn.",404);Version(row,i.Version);row.Note=Clean(i.Body);row.UpdatedAt=clock.BayGioUtc;c.UpdatedAt=clock.BayGioUtc;return;}
   if(i.Decision=="Remove"){var row=await db.Set<DiscoveryCollectionItem>().SingleOrDefaultAsync(x=>x.CollectionId==c.Id&&x.EntryId==i.EntryId)??throw new BusinessException("Không tìm thấy lựa chọn.",404);Version(row,i.Version);row.Removed=true;row.UpdatedAt=clock.BayGioUtc;}
   else{var keys=(i.Decision=="Import"?i.EntryIds:[i.EntryId]).Distinct().ToList();var visible=await Public().Where(x=>keys.Contains(x.Id)).Select(x=>x.Id).ToListAsync();Need(visible.Count==keys.Count,"Có lựa chọn đã ẩn hoặc chưa công bố. Hãy bỏ lựa chọn đó rồi thử lại.");var activeKeys=await db.Set<DiscoveryCollectionItem>().Where(x=>x.CollectionId==c.Id&&!x.Removed).Select(x=>x.EntryId).ToListAsync();Need(activeKeys.Count+keys.Except(activeKeys).Count()<=100,"Mỗi danh sách tối đa 100 lựa chọn.");foreach(var key in keys){var row=await db.Set<DiscoveryCollectionItem>().SingleOrDefaultAsync(x=>x.CollectionId==c.Id&&x.EntryId==key);if(row==null){row=new(){CollectionId=c.Id,EntryId=key};db.Add(row);}else if(!row.Removed)continue;row.Note=Clean(i.Body);row.Removed=false;row.UpdatedAt=clock.BayGioUtc;}}
   c.UpdatedAt=clock.BayGioUtc;
  });
 }
 public async Task SaveRoute(DiscoveryRouteInput i)
 {
  Signed();Validate(i);Need(!string.IsNullOrWhiteSpace(i.Name)&&i.Name.Length<=100,"Đặt tên tuyến tối đa 100 ký tự.");ValidatePoints(i.Points,i.Mode);Need(i.SubmissionId!=Guid.Empty,"Mã lưu tuyến không hợp lệ.");await travel.Execute(async()=>{if(await db.Set<DiscoveryRoute>().AnyAsync(x=>x.OwnerId==Me&&x.SubmissionId==i.SubmissionId))return;Need(await db.Set<DiscoveryRoute>().CountAsync(x=>x.OwnerId==Me&&!x.Archived)<30,"Bạn đã lưu 30 tuyến.");db.Add(new DiscoveryRoute{OwnerId=Me,Name=i.Name.Trim(),PointsJson=JsonSerializer.Serialize(i.Points),Mode=i.Mode,SubmissionId=i.SubmissionId,UpdatedAt=clock.BayGioUtc});});
 }
 public async Task ArchiveRoute(DiscoveryCommand i){Signed();await travel.Execute(async()=>{var x=await db.Set<DiscoveryRoute>().SingleOrDefaultAsync(x=>x.Id==i.Id&&x.OwnerId==Me)??throw new BusinessException("Không tìm thấy tuyến của bạn.",404);Version(x,i.Version);x.Archived=true;x.UpdatedAt=clock.BayGioUtc;});}
 internal void ValidatePoints(List<DiscoveryPoint> points,string mode){Need(new[]{"car","foot","bike"}.Contains(mode)&&points.Count is >=2 and <=8&&points.All(p=>double.IsFinite(p.Lat)&&double.IsFinite(p.Lng)&&p.Lat is >=-90 and <=90&&p.Lng is >=-180 and <=180&&(p.Name?.Length??0)<=100),"Tuyến cần 2 đến 8 vị trí hợp lệ và phương tiện được hỗ trợ.",400);}
}
